"""Original sodium chapter: emergencies, hypernatremia and AVP disorders."""
from create_sodium import rows,q,HY,HS,DI
from qbank_authoring import ref,finalize
EM=ref('Society for Endocrinology: Emergency Management of Severe Symptomatic Hyponatraemia','https://pmc.ncbi.nlm.nih.gov/articles/PMC5314809/')
TV=ref('SAMSCA (tolvaptan): Current U.S. Prescribing Information','https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=5526617c-c7b9-4556-886d-729bbabbc566')
CP=ref('Refardt et al. Arginine or Hypertonic Saline–Stimulated Copeptin to Diagnose AVP Deficiency. NEJM 2023','https://www.nejm.org/doi/full/10.1056/NEJMoa2306263')
ND=ref('International Expert Consensus: Congenital Nephrogenic Diabetes Insipidus, 2025','https://www.nature.com/articles/s41581-024-00897-z')
q('A patient with sodium 109 mmol/L has an ongoing generalized seizure. What is the immediate sodium-directed treatment?', 'Controlled bolus administration of 3% saline with rapid reassessment and close monitoring',[
 ('Fluid restriction alone while awaiting a complete etiological work-up','Severe neurological symptoms require immediate therapy.'),('Oral tolvaptan as the emergency treatment','It is not appropriate for urgent symptom rescue and can cause uncontrolled correction.'),('Normalize sodium to 140 mmol/L in the first few hours','Only a modest initial rise is needed; full rapid correction is hazardous.')],
 'Reverse cerebral edema with a modest controlled rise', '**Use a validated hypertonic bolus protocol, such as 150 mL over 20 minutes in European guidance.**',['Reassess symptoms and sodium after each bolus.','An initial rise of about 4–6 mmol/L often suffices for symptom relief.'], '**Stop repeated boluses once the initial goal is achieved.**',['Maintain airway and seizure care.','Investigate the cause without delaying emergency treatment.'],[['Emergency','Seizure or severe neurological symptoms'],['Initial aim','About 4–6 mmol/L rise'],['Later aim','Prevent excessive total correction']],[EM,HY],'clinical_scenario')
q('A malnourished patient with chronic sodium 104 mmol/L is receiving treatment. Which correction plan is safest?', 'Aim for a modest rise and keep the increase at no more than 8 mmol/L in any 24 hours because of high ODS risk',[
 ('Target at least 16 mmol/L in the first day','This is unsafe in a high-risk chronic case.'),('Allow unlimited correction after the first hypertonic bolus','The initial bolus counts toward the daily rise.'),('Use the correction ceiling as a required minimum','A ceiling is a limit, not a target.')],
 'High-risk chronic disease requires stricter limits', '**Profound hyponatremia, malnutrition, alcohol use, hypokalemia and advanced liver disease increase ODS risk.**',['A usual high-risk goal is about 4–6 mmol/L per day.','Count every source of correction, including spontaneous water diuresis.'], '**Use rolling intervals and serial measurements.**',['Plan below the ceiling to allow for laboratory variation.','Have a rescue strategy ready before a rapid aquaresis occurs.'],[['High-risk goal','Modest 4–6 mmol/L/day'],['High-risk ceiling','8 mmol/L in 24 hours'],['Total rise','Includes all interventions']],[HS,HY],'clinical_scenario')
q('During treatment of chronic hyponatremia, urine output suddenly rises to 500 mL/hour and sodium is increasing faster than planned. What is the best response?', 'Stop ongoing sodium-raising therapy and urgently assess desmopressin plus electrolyte-free water to prevent or reverse overcorrection',[
 ('Continue the same saline rate until the next morning','A sudden aquaresis can cause dangerous overshoot.'),('Add a vaptan to slow sodium correction','A vaptan increases water excretion and can worsen overshoot.'),('Assume a correction formula guarantees the final sodium','Formulas cannot predict abrupt changes in urine water losses.')],
 'Spontaneous water diuresis is a common overshoot mechanism', '**Desmopressin can limit renal free-water excretion.**',['D5W can replace water or relower sodium under close supervision.','Relowering decisions depend on rise, duration and ODS risk.'], '**Increase monitoring and obtain experienced help.**',['Track urine output as well as sodium.','Recheck response repeatedly rather than using a fixed unobserved infusion.'],[['Warning','Brisk dilute urine'],['Antidiuresis','Desmopressin'],['Water replacement','Carefully titrated D5W']],[HY,HS,EM],'clinical_scenario')
q('Why must potassium replacement be included in the sodium-correction plan for a patient with hyponatremia and hypokalemia?', 'Retained potassium contributes to effective body cation content and can raise serum sodium',[
 ('Potassium has no effect on serum sodium','Serum sodium relates to exchangeable sodium plus potassium and body water.'),('Correcting potassium always lowers sodium','The direction is not reliably downward and can promote correction.'),('Hypokalemia protects the brain from ODS','Hypokalemia is a recognized risk factor.')],
 'Potassium is part of the effective cation balance', '**Correcting potassium can increase serum sodium even without sodium administration.**',['Intracellular shifts and water distribution contribute.','Potassium depletion itself requires appropriate treatment.'], '**Treat both disorders with a combined monitored prescription.**',['Do not omit necessary potassium; account for its effect.','Monitor ECG and serial electrolytes according to severity.'],[['Replacement','Potassium can raise sodium'],['Risk','Hypokalemia increases ODS susceptibility'],['Plan','Integrated cation and water monitoring']],[HY,HS])
q('A predicted sodium rise from an infusion formula differs markedly from the observed rise after volume restoration. What is the main limitation of the formula?', 'It cannot reliably anticipate changing urinary water and electrolyte losses',[
 ('It directly measures vasopressin secretion','It is a mass-balance estimate, not a hormone assay.'),('It guarantees safety if the starting weight is correct','Dynamic losses can invalidate the estimate.'),('It includes every future change in renal function','Renal physiology can change during treatment.')],
 'A calculation is a starting estimate', '**Volume restoration can remove the antidiuretic stimulus and generate aquaresis.**',['Insensible and gastrointestinal losses can also change.','Body-water estimates are imperfect.'], '**Adjust treatment to observed response.**',['Use frequent sodium and urine monitoring.','Do not substitute a calculated final value for serial measurements.'],[['Formula','Static estimate'],['Physiology','Dynamic losses'],['Safety','Observed trajectory']],[HY])
q('For the U.S. SAMSCA indication, which statement about tolvaptan is correct?', 'Initiate or reinitiate in hospital with sodium monitoring; limit treatment to 30 days and observe liver precautions',[
 ('Use it for hypovolemic hyponatremia','Hypovolemia is a contraindication.'),('Use it as the standard immediate rescue for seizures','Urgent neurological rescue requires hypertonic saline.'),('Its hyponatremia label allows indefinite unmonitored therapy','Duration and monitoring restrictions apply.')],
 'A V2 antagonist can correct sodium too quickly', '**Tolvaptan causes electrolyte-free water excretion.**',['Patients must be able to respond to thirst.','Liver injury precautions and drug interactions require review.'], '**Distinguish the hyponatremia label from the ADPKD treatment program.**',['Do not transfer dosing or duration rules between indications.','Guideline recommendations and local licensing also affect selection.'],[['Action','Aquaresis'],['U.S. hyponatremia duration','No more than 30 days'],['Initiation','Hospital monitoring']],[TV])
q('Several days after excessive correction of profound chronic hyponatremia, a patient develops dysarthria, dysphagia and quadriparesis. Which complication is most concerning?', 'Osmotic demyelination syndrome',[
 ('Acute cerebral edema from further sodium lowering as the established cause','The delayed deterioration after rapid correction points to ODS.'),('Uremic neuropathy as the best explanation for this timing','The temporal relationship is more characteristic of ODS.'),('SIAD itself necessarily causing the delayed focal syndrome','New neurological signs need evaluation for treatment-related injury and alternatives.')],
 'Neurological injury can be delayed after apparent improvement', '**Osmotic adaptation to chronic hypotonicity makes rapid reversal hazardous.**',['Pontine and extrapontine regions can be affected.','Early MRI can be unrevealing.'], '**Preventive correction control is crucial.**',['Investigate other acute neurological causes in parallel.','Management requires specialist supportive and neurological care.'],[['Timing','Often delayed days'],['Risk','Rapid correction in a susceptible host'],['Regions','Pontine or extrapontine']],[HY,HS],'clinical_scenario')
q('What does hypernatremia usually indicate about the relationship between body water and exchangeable sodium plus potassium?', 'A relative deficit of water compared with effective body cations',[
 ('An obligatory increase in total body sodium in every case','Pure water loss can cause hypernatremia without sodium excess.'),('Normal tonicity regardless of the sodium value','Hypernatremia generally signifies hypertonicity.'),('A diagnosis of SIAD','SIAD promotes water retention and usually hyponatremia.')],
 'Hypernatremia is a water-to-cation imbalance', '**Water loss is common, while hypertonic sodium gain is another mechanism.**',['Thirst and water access normally defend against sustained hypernatremia.','Impaired cognition or dependence can make ordinary losses dangerous.'], '**Assess both circulation and the source of water imbalance.**',['Separate renal from extrarenal losses.','Review fluid prescriptions and sodium-containing therapies.'],[['Common mechanism','Water loss'],['Alternative','Hypertonic sodium gain'],['Defense','Thirst and water access']],[DI])
q('An obtunded hypernatremic patient is hypotensive with poor peripheral perfusion. What is the initial fluid priority?', 'Restore effective circulation with an appropriate isotonic crystalloid before completing free-water correction',[
 ('Use only enteral water while shock persists','Circulatory resuscitation takes priority.'),('Withhold all fluids because sodium is high','This leaves shock untreated.'),('Rapidly normalize sodium with a large D5W bolus regardless of circulation','This is not the initial resuscitation strategy.')],
 'Volume resuscitation and free-water replacement serve different goals', '**Shock requires restoration of perfusion.**',['After stabilization, enteral water or an appropriate hypotonic infusion can address the deficit.','Ongoing losses must also be replaced.'], '**Reassess sodium throughout resuscitation.**',['Avoid a fixed one-bag plan.','Choose subsequent water delivery according to chronicity and observed correction.'],[['First','Restore perfusion'],['Then','Correct water deficit'],['Throughout','Monitor sodium and losses']],[DI],'clinical_scenario')
q('A patient has estimated total body water of 30 L and sodium 160 mmol/L. Using a target of 140, what is the approximate calculated water deficit before ongoing losses?', '4.3 L',[
 ('0.6 L','This underestimates 30 × (160/140 − 1).'),('15 L','This substantially overestimates the specified calculation.'),('30 L','This is the estimated total body water, not the deficit.')],
 'Water deficit is an estimate, not a complete prescription', '**Deficit = total body water × (current sodium / target sodium − 1).**',['Here 30 × 0.1429 is about 4.3 L.','The total-body-water estimate depends on age, sex and body composition.'], '**Add ongoing and insensible losses while observing the actual response.**',['Do not give the entire estimate rapidly in chronic disease.','Volume resuscitation may be a separate initial need.'],[['TBW','30 L'],['Ratio minus one','0.1429'],['Estimated deficit','About 4.3 L']],[DI])
q('Which approach is generally used for chronic or unknown-duration hypernatremia in a stable adult?', 'Controlled water replacement with frequent reassessment, commonly planning a fall no faster than about 0.5 mmol/L/hour or 10 mmol/L/day',[
 ('Normalize sodium in one hour in every case','This disregards chronic cerebral adaptation.'),('Leave marked hypernatremia untreated for several days','Underreplacement also carries harm.'),('Apply the same correction rule without considering acute sodium loading','Documented acute disease may need a different expert strategy.')],
 'Duration changes the correction strategy', '**Traditional guidance favors gradual correction in chronic or uncertain-duration disease.**',['Adult evidence for exact thresholds is limited and evolving.','Severe acute sodium loading is a different scenario.'], '**Avoid both uncontrolled rapid shifts and prolonged inadequate replacement.**',['Track sodium and urine output frequently.','Adjust to symptoms, duration and observed trend.'],[['Chronic/unknown','Gradual monitored replacement'],['Acute loading','Separate expert assessment'],['Evidence','Exact adult limits remain debated']],[DI])
q('Hypernatremia is accompanied by high-volume urine with very low osmolality. Which mechanism should be prioritized?', 'Impaired vasopressin secretion or renal response',[
 ('Appropriate maximal renal concentration after isolated sweating','That should produce concentrated urine.'),('SIAD with excessive water retention','This does not fit dilute renal water loss.'),('Only extrarenal loss with an intact concentrating response','The inappropriate dilution points to renal loss.')],
 'The urine should concentrate during hypertonicity', '**Dilute polyuria despite hypernatremia suggests AVP deficiency or resistance.**',['Osmotic diuresis usually has a larger urinary osmole burden.','Check glucose, calcium, potassium and relevant medications.'], '**Protect water access and assess the cause.**',['Measure volume and urine osmolality rather than relying on frequency alone.','Severe illness needs supervised fluid and hormone management.'],[['Expected defense','Concentrated urine'],['Observed mismatch','Dilute polyuria'],['Differential','AVP deficiency/resistance']],[DI,ND],'clinical_scenario')
q('During a supervised assessment of complete hypotonic polyuria, urine osmolality increases markedly after desmopressin. Which diagnosis is favored?', 'Arginine vasopressin deficiency',[
 ('Complete renal vasopressin resistance','The kidney would respond poorly.'),('Glucose-driven osmotic diuresis as proven by the response','That requires glucose and osmole assessment.'),('Primary polydipsia conclusively excluded in every partial case','Partial disorders and chronic water loading can overlap.')],
 'Hormone replacement tests renal responsiveness', '**A substantial response supports deficient endogenous AVP secretion.**',['A poor response suggests resistance in a complete syndrome.','Partial deficiency and partial resistance complicate interpretation.'], '**Use validated specialist testing.**',['Water deprivation can be dangerous in hypernatremic or vulnerable patients.','Copeptin-based testing may improve differentiation.'],[['AVP deficiency','Responds to replacement'],['AVP resistance','Blunted response'],['Partial syndromes','Overlap possible']],[DI,CP])
q('What does copeptin provide in the evaluation of hypotonic polyuria?', 'A stable surrogate marker of endogenous vasopressin secretion',[
 ('A direct measurement of renal aquaporin abundance','It reflects hormone secretion rather than channel expression.'),('A stand-alone diagnosis independent of osmotic stimulus','Interpretation depends on the test protocol and context.'),('A replacement for confirming true polyuria','Urine volume and hypotonicity should first be established.')],
 'Stimulated testing asks whether AVP secretion is appropriate', '**Hypertonic-saline-stimulated copeptin can distinguish AVP deficiency from primary polydipsia in expert settings.**',['The 2023 head-to-head trial found higher accuracy than the specified arginine test.','Sodium monitoring is essential during hypertonic stimulation.'], '**Apply validated protocol-specific cutoffs.**',['Do not transplant thresholds between tests or assays.','Clinical safety determines which test is suitable.'],[['Marker','Copeptin'],['Interpretation','Stimulus and assay dependent'],['Safety','Specialist monitored testing']],[CP])
q('Which acquired disturbance can cause renal vasopressin resistance?', 'Hypercalcemia or hypokalemia',[
 ('Isolated increased AVP secretion with a normal renal response','That promotes water retention rather than resistance.'),('Cortisol deficiency as the typical cause of dilute hypernatremic polyuria','It more often impairs water excretion.'),('SIAD from an SSRI','This produces inappropriate antidiuresis.')],
 'Electrolyte disorders can impair urinary concentration', '**Hypercalcemia and potassium depletion can reduce the kidney’s response to AVP.**',['Lithium is another major acquired cause.','Treating the driver may improve the defect.'], '**Correct the cause and maintain appropriate water replacement.**',['Monitor recovery to avoid continuing an obsolete fluid prescription.','Assess kidney function and drug toxicity.'],[['Electrolytes','High calcium/low potassium'],['Drug','Lithium'],['Management','Cause correction plus water plan']],[ND])
q('A hospitalized patient with known AVP deficiency cannot access water and misses desmopressin doses. Which outcome is especially dangerous?', 'Rapid dehydration and hypernatremia from uncontrolled dilute urine loss',[
 ('Guaranteed stable sodium because thirst alone is sufficient','Thirst is ineffective when water access or consciousness is impaired.'),('Mandatory SIAD from missed desmopressin','Missing replacement promotes water loss.'),('No harm until creatinine becomes severely elevated','Severe hypernatremia can develop before that endpoint.')],
 'Dependence on water access and replacement creates an inpatient safety risk', '**Medication omission can become a medical emergency.**',['Identify the established regimen at admission.','Assess cognition, thirst and ability to obtain fluids.'], '**Provide a supervised fluid and desmopressin plan.**',['Monitor urine and sodium closely during decompensation.','Avoid uncontrolled concurrent water loading after antidiuresis is restored.'],[['Omitted replacement','Polyuria'],['Limited access','No compensation by drinking'],['Prevention','Medication and fluid continuity']],[DI],'clinical_scenario')
q('Why is adipsic AVP deficiency particularly difficult to manage?', 'Both the antidiuretic hormone response and the thirst defense are impaired',[
 ('The kidney necessarily has irreversible complete AVP resistance','Hormone deficiency and impaired thirst do not imply renal resistance.'),('Patients automatically adjust water intake normally','The thirst signal is impaired.'),('Desmopressin eliminates all need for a fluid plan','Water intake still needs deliberate control.')],
 'Two defenses against hypernatremia can fail together', '**Absent thirst prevents intuitive replacement of urinary or insensible losses.**',['A prescribed fluid intake and body-weight plan may be needed.','Desmopressin reduces urine losses but cannot regulate drinking by itself.'], '**Use individualized education and biochemical follow-up.**',['Intercurrent illness changes fluid requirements.','Caregiver support may be essential.'],[['Defect one','AVP deficiency'],['Defect two','Absent or reduced thirst'],['Plan','Hormone plus scheduled water']],[DI],'clinical_scenario')
q('A patient treated with desmopressin develops hyponatremia after drinking large volumes of water. What is the key mechanism?', 'Persistent antidiuresis limits excretion of excess ingested water',[
 ('Desmopressin causes obligate sodium secretion in every patient','Its principal effect is water retention.'),('The diagnosis must be a new renal salt-wasting syndrome','The treatment and intake history provide a direct mechanism.'),('Water intake cannot affect sodium during replacement','Excess intake is particularly hazardous during antidiuresis.')],
 'Replacement can become excessive relative to water intake', '**Desmopressin-induced antidiuresis can produce dilutional hyponatremia.**',['Review dosing, renal function and fluid intake.','Abrupt withdrawal in severe chronic hyponatremia can provoke a rapid aquaresis.'], '**Manage severe cases with an experienced monitored plan.**',['Avoid uncontrolled sodium correction from simply withholding all replacement.','Teach a safe long-term regimen and illness precautions.'],[['Exposure','Desmopressin plus excess water'],['Result','Dilutional hyponatremia'],['Withdrawal risk','Brisk water diuresis']],[DI,HY],'clinical_scenario')

if __name__=='__main__':finalize('Nephrology',7,'Sodium and Water Disorders','neph-sodium-water',rows,36)
